}
const scores: ScoreBoard = { Alice: 95, Bob: 80 };
scores.Charlie = 88;

// 2. 매핑된 타입: 모든 필드를 읽기 전용 또는 불리언 플래그로 변환
interface Features {
    darkMode: () => void;
